let params=new URLSearchParams(location.search),lang=params.get('lang')==='en'?'en':'ar',draft=null,activeSuggestion=-1,suggestTimer;
const t=k=>text[k]?.[lang==='ar'?0:1]||k;
const cats={home:'homeCat',fashion:'fashion',electronics:'electronics',beauty:'beauty',sports:'sports'};
const labels={A:['دولة ألف · اختبار','Country A · test'],B:['دولة باء · اختبار','Country B · test'],North:['الشمال','North'],South:['الجنوب','South'],Coast:['الساحل','Coast'],Garden:['مدينة الحديقة','Garden city'],Port:['مدينة الميناء','Port city'],Bay:['مدينة الخليج','Bay city']};
const label=v=>labels[v]?.[lang==='ar'?0:1]||v;
