function read(){return Object.fromEntries(['q','scope','category','brand','store','country','region','city','min','max','rating','sort','currency','page'].map(k=>[k,params.get(k)||'']).concat(['free','stock','offer'].map(k=>[k,params.get(k)==='1']),[['badges',(params.get('badges')||'').split(',').filter(x=>['registered','verified','excellent','official'].includes(x))]]))}
function write(f,{replace=false}={}){const next=new URLSearchParams();next.set('lang',lang);Object.entries(f).forEach(([k,v])=>{if(Array.isArray(v)){if(v.length)next.set(k,v.join(','))}else if(v!==''&&v!==false&&v!=null)next.set(k,v===true?'1':String(v))});params=next;history[replace?'replaceState':'pushState'](null,'',`${location.pathname}?${next}`);render()}
function options(values,chosen){return `<option value="">${t('any')}</option>`+values.map(([v,l])=>`<option value="${esc(v)}" ${v===chosen?'selected':''}>${esc(l)}</option>`).join('')}
function selectField(key,title,values,f){return `<label class="field">${title}<select name="${key}">${options(values,f[key])}</select></label>`}
function checkbox(key,labelText,f,disabled=false){return `<label class="check"><input type="checkbox" name="${key}" ${f[key]?'checked':''} ${disabled?'disabled':''}><span>${labelText}</span></label>`}
function facetHtml(f){const result=P.search({...f,category:''}),zones=F.stores.flatMap(s=>s.zones),regions=[...new Set(zones.filter(z=>z.country===f.country).map(z=>z.region))],cities=[...new Set(zones.filter(z=>z.country===f.country&&z.region===f.region).map(z=>z.city))];return `<div class="facet-heading"><h2>${t('filters')}</h2><button class="clear-button" type="button" data-clear>${t('clear')}</button></div><fieldset class="filter-section"><legend>${t('category')}</legend>${Object.entries(cats).map(([v,k])=>`<label class="check"><input type="radio" name="category" value="${v}" ${f.category===v?'checked':''}><span>${t(k)}</span><span class="count">${result.facets[v]}</span></label>`).join('')}</fieldset><div class="filter-section"><b>${t('price')}</b><div class="range">${['min','max'].map(k=>`<label class="field">${t(k)}<input type="number" name="${k}" min="0" max="100000" step="1" value="${esc(f[k])}"></label>`).join('')}</div></div><div class="filter-section">${selectField('brand',t('brand'),[...new Set(F.products.map(p=>p.brand))].map(b=>[b,b]),f)}${selectField('store',t('store'),F.stores.map(s=>[s.id,s.name]),f)}</div><div class="filter-section"><b>${t('destination')}</b>${selectField('country',t('country'),['A','B'].map(v=>[v,label(v)]),f)}${selectField('region',t('region'),regions.map(v=>[v,label(v)]),f)}${selectField('city',t('city'),cities.map(v=>[v,label(v)]),f)}${checkbox('free',t('free'),f,!(f.country&&f.region&&f.city))}<p class="hint">${t('freeHint')}</p></div><fieldset class="filter-section"><legend>${t('badge')}</legend>${['registered','verified','excellent','official'].map(b=>`<label class="check"><input type="checkbox" name="badges" value="${b}" ${f.badges.includes(b)?'checked':''}><span class="trust-badge ${b}"><span class="seal"><b>✓</b></span>${t(b)}</span></label>`).join('')}<p class="hint">${t('badgeHint')}</p></fieldset><div class="filter-section">${selectField('rating',t('rating'),[['4','4+'],['4.5','4.5+']],f)}${checkbox('stock',t('stock'),f)}${checkbox('offer',t('offer'),f)}</div>`}
function badges(s){return P.validBadges(s).filter(b=>b!=='registered').slice(0,2).map(b=>`<span class="trust-badge ${b}" title="${esc(t('badgeInfo'))}"><span class="seal" aria-hidden="true"><b>✓</b></span>${t(b)} · ${lang==='ar'?'عينة':'sample'}</span>`).join('')}
function card(p,f){const s=F.stores.find(s=>s.id===p.store_id),z=P.zone(s,f),shipping=f.country&&f.region&&f.city&&z?(z.fee===0?t('freeShort'):`${t('shipping')} ${money(z.fee)}`):t('unknown');return `<article class="result-card"><button class="card-open" data-product="${p.id}" aria-label="${esc(lang==='ar'?p.ar:p.name)}"><img class="card-image" src="${p.image}" alt="${esc(lang==='ar'?p.ar:p.name)}" loading="lazy" width="320" height="320">${p.oldPrice>p.price?`<span class="promotion">−${Math.round((1-p.price/p.oldPrice)*100)}% · ${lang==='ar'?'عينة':'sample'}</span>`:''}</button><div class="card-info"><button class="card-title" data-product="${p.id}">${esc(lang==='ar'?p.ar:p.name)}</button><p class="card-price">${money(p.price)}${p.oldPrice>p.price?`<del>${money(p.oldPrice)}</del>`:''}</p><p class="card-store">${esc(s.name)}</p><div class="badge-row">${badges(s)}</div><p class="card-shipping">${shipping}</p><div class="card-stock">${t(p.stock?'available':'unavailable')}</div></div></article>`}
function storeCard(s,scope){return `<article class="store-result"><span class="store-initial" aria-hidden="true">${esc(s.name[0])}</span><h3>${esc(scope==='sellers'?(lang==='ar'?s.seller_ar:s.seller):s.name)}</h3><p>${t(scope==='sellers'?'sellerPublic':'testStore')}</p><div class="badge-row">${badges(s)}</div><button data-store="${s.id}">${t('view')}</button></article>`}
function render(){const f=read(),r=P.search(f),scope=f.scope||'all';document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=`BEMO · ${t('search')} · ${t('sample')}`;[['reviewText','review'],['originalLink','original'],['homeLink','home'],['queryLabel','placeholder'],['searchButton','search'],['breadcrumb','breadcrumb'],['kicker','kicker'],['sampleLabel','sample'],['sortLabel','sort'],['boundaryTitle','boundaryTitle'],['boundaryText','boundaryText'],['filterTitle','filters'],['filterButton','filters'],['applyMobile','apply'],['resetMobile','reset']].forEach(([id,k])=>$('#'+id).textContent=t(k));$('#heading').textContent=f.q?`${t('search')}: «${f.q}»`:t('heading');$('#query').value=f.q;$('#query').placeholder=t('placeholder');$('#language').textContent=lang==='ar'?'English':'العربية';$('#closeFilters').setAttribute('aria-label',t('close'));$('#closeDetail').setAttribute('aria-label',t('close'));$('#homeLink').href=`index.html?lang=${lang}`;$('#scopes').innerHTML=['all','products','stores','sellers'].map(s=>`<button class="${s===scope?'active':''}" data-scope="${s}" aria-pressed="${s===scope}">${t(s)}</button>`).join('');$('#facets').innerHTML=facetHtml(f);$('#sort').innerHTML=['relevance','newest','price_up','price_down','rating','discount'].map(v=>`<option value="${v}" ${f.sort===v?'selected':''}>${t(v==='rating'?'ratingSort':v)}</option>`).join('');$('#sort').setAttribute('aria-label',t('sort'));const productScope=['products','all'].includes(scope),storeScope=['stores','sellers','all'].includes(scope);$('#resultCount').textContent=`${productScope?r.total:0}${scope==='all'?` + ${r.stores.length}`:storeScope?r.stores.length:''} ${t('results')}`;if(!productScope)$('#resultCount').textContent=`${r.stores.length} ${t('results')}`;$('#results').innerHTML=productScope&&r.total?r.items.map(p=>card(p,f)).join(''):!r.stores.length||scope==='products'?`<div class="empty-state"><h2>${t('empty')}</h2><p>${t('emptyText')}</p><button data-clear>${t('resetFilters')}</button></div>`:'';$('#storeResults').innerHTML=storeScope?r.stores.map(s=>storeCard(s,scope)).join(''):'';$('#shippingHint').textContent=Number(f.max)&&Number(f.min)>Number(f.max)?t('priceError'):t(!f.country?'noDestination':!f.region||!f.city?'partial':'complete');const chipKeys=['category','brand','store','country','region','city','min','max','rating','free','stock','offer'];$('#chips').innerHTML=chipKeys.filter(k=>f[k]).map(k=>`<button data-chip="${k}">${esc(k==='category'?t(cats[f[k]]):k==='store'?F.stores.find(s=>s.id===f[k])?.name:k==='min'||k==='max'?`${t(k)} ${f[k]}`:['free','stock','offer'].includes(k)?t(k):label(f[k]))} ×</button>`).join('')+f.badges.map(b=>`<button data-badge-chip="${b}">${t(b)} ×</button>`).join('');$('#pagination').innerHTML=productScope&&r.total?Array.from({length:r.pages},(_,i)=>`<button data-page="${i+1}" class="${r.page===i+1?'active':''}" aria-label="${lang==='ar'?'صفحة':'Page'} ${i+1}" ${r.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join(''):'';$('#bottomNav').innerHTML=`<a href="index.html?lang=${lang}">${t('home')}</a><a class="active" href="search.html?lang=${lang}">${t('categories')}</a><a href="search.html?offer=1&lang=${lang}">${t('deals')}</a><a href="../">${t('cart')}</a><a href="#boundaryTitle">${t('account')}</a>`;}
function change(f,el){const key=el.name;if(!key)return;f.page='1';if(key==='badges')f.badges=el.checked?[...new Set([...f.badges,el.value])]:f.badges.filter(b=>b!==el.value);else f[key]=el.type==='checkbox'?el.checked:el.value;if(key==='country'){f.region='';f.city='';f.free=false}if(key==='region'){f.city='';f.free=false}if(key==='city')f.free=false;return f}
function restoreFacetFocus(root,field){const match=[...root.querySelectorAll('[name]')].find(el=>el.name===field.name&&(!['radio','checkbox'].includes(el.type)||el.value===field.value));match?.focus({preventScroll:true})}
$('#facets').addEventListener('change',ev=>{const field={name:ev.target.name,value:ev.target.value},next=change(read(),ev.target);if(next){write(next);restoreFacetFocus($('#facets'),field)}});$('#mobileFacets').addEventListener('change',ev=>{const field={name:ev.target.name,value:ev.target.value};change(draft,ev.target);if(['country','region','city'].includes(field.name)){$('#mobileFacets').innerHTML=facetHtml(draft);restoreFacetFocus($('#mobileFacets'),field)}});
document.addEventListener('click',ev=>{const el=ev.target.closest('button');if(!el)return;const f=read();if(el.hasAttribute('data-clear')){const next={q:f.q,scope:f.scope,badges:[]};if(el.closest('#filterDialog')){draft={...read(),...Object.fromEntries(Object.keys(read()).map(k=>[k,''])),...next};$('#mobileFacets').innerHTML=facetHtml(draft)}else write(next)}if(el.dataset.scope)write({...f,scope:el.dataset.scope,page:1});if(el.dataset.page){write({...f,page:el.dataset.page});$('.result-controls').scrollIntoView({block:'start'})}if(el.dataset.chip){f[el.dataset.chip]='';if(el.dataset.chip==='country'){f.region='';f.city='';f.free=false}if(el.dataset.chip==='region'){f.city='';f.free=false}if(el.dataset.chip==='city')f.free=false;write({...f,page:1})}if(el.dataset.badgeChip)write({...f,badges:f.badges.filter(b=>b!==el.dataset.badgeChip),page:1});if(el.dataset.store)write({...f,q:'',store:el.dataset.store,scope:'products',page:1});if(el.dataset.product){const p=F.products.find(p=>p.id===+el.dataset.product);$('#detailTitle').textContent=t('details');$('#detailBody').innerHTML=`<img src="${p.image}" alt="${esc(lang==='ar'?p.ar:p.name)}"><h3>${esc(lang==='ar'?p.ar:p.name)}</h3><strong>${money(p.price)}</strong><p>${t('detailNote')}</p><p>${t('badgeInfo')}</p><a href="../">${t('original')}</a>`;$('#detailDialog').showModal()}});
$('#searchForm').addEventListener('submit',ev=>{ev.preventDefault();$('#suggestions').hidden=true;$('#query').setAttribute('aria-expanded','false');write({...read(),q:$('#query').value.trim(),page:1})});$('#sort').addEventListener('change',ev=>write({...read(),sort:ev.target.value,page:1}));$('#language').addEventListener('click',()=>{lang=lang==='ar'?'en':'ar';write(read())});
function closeSheet(fromBack=false){$('#filterDialog').close();draft=null;if(!fromBack&&history.state?.filterSheet)history.back()}
$('#filterButton').addEventListener('click',()=>{draft=read();$('#mobileFacets').innerHTML=facetHtml(draft);history.pushState({filterSheet:true},'',location.href);$('#filterDialog').showModal()});$('#closeFilters').addEventListener('click',()=>closeSheet());$('#filterDialog').addEventListener('cancel',ev=>{ev.preventDefault();closeSheet()});$('#applyMobile').addEventListener('click',()=>{const next={...draft};$('#filterDialog').close();draft=null;history.replaceState(null,'',location.href);write(next,{replace:true})});$('#resetMobile').addEventListener('click',()=>{draft={q:draft.q,scope:draft.scope,badges:[]};$('#mobileFacets').innerHTML=facetHtml(draft)});$('#closeDetail').addEventListener('click',()=>$('#detailDialog').close());
window.addEventListener('popstate',()=>{if($('#filterDialog').open)closeSheet(true);params=new URLSearchParams(location.search);lang=params.get('lang')==='en'?'en':'ar';render()});
$('#query').addEventListener('input',()=>{clearTimeout(suggestTimer);suggestTimer=setTimeout(()=>{const q=$('#query').value.trim(),list=q?P.suggest(q):[];activeSuggestion=-1;$('#suggestions').innerHTML=list.map((p,i)=>`<li role="option" id="suggest-${i}" data-value="${esc(lang==='ar'?p.ar:p.name)}" aria-selected="false">${esc(lang==='ar'?p.ar:p.name)}</li>`).join('');$('#suggestions').hidden=!list.length;$('#query').setAttribute('aria-expanded',String(!!list.length));$('#query').removeAttribute('aria-activedescendant')},250)});
function selectSuggestion(el){$('#query').value=el.dataset.value;$('#suggestions').hidden=true;$('#query').setAttribute('aria-expanded','false');$('#query').removeAttribute('aria-activedescendant');write({...read(),q:el.dataset.value,page:1});$('#query').focus()}
$('#suggestions').addEventListener('click',ev=>{const el=ev.target.closest('[data-value]');if(el)selectSuggestion(el)});$('#query').addEventListener('keydown',ev=>{const list=[...$('#suggestions').children];if(ev.key==='Escape'){$('#suggestions').hidden=true;$('#query').setAttribute('aria-expanded','false')}if(!list.length||$('#suggestions').hidden)return;if(['ArrowDown','ArrowUp'].includes(ev.key)){ev.preventDefault();activeSuggestion=(activeSuggestion+(ev.key==='ArrowDown'?1:-1)+list.length)%list.length;list.forEach((el,i)=>el.setAttribute('aria-selected',i===activeSuggestion));$('#query').setAttribute('aria-activedescendant',list[activeSuggestion].id)}if(ev.key==='Enter'&&activeSuggestion>=0){ev.preventDefault();selectSuggestion(list[activeSuggestion])}});document.addEventListener('click',ev=>{if(!ev.target.closest('#searchForm')){$('#suggestions').hidden=true;$('#query').setAttribute('aria-expanded','false')}});render();
